def solve():
    import sys
    t = int(sys.stdin.readline())
    for _ in range(t):
        s = sys.stdin.readline().strip()
        n = len(s)
        if n % 2 != 0:
            print("NO")
            continue
        half = n // 2
        if s[:half] == s[half:]:
            print("YES")
        else:
            print("NO")

solve()
